#!/usr/bin/env node
/**
 * Single-sources the audio renderer's shared logic from the client source of truth:
 *
 *   src/lib/narratorCore.ts  ->  supabase/functions/audio-render/narratorCore.ts  (verbatim copy)
 *
 * The renderer and the app must never disagree about who reads today, what he may say,
 * or the exact words of the script — a drifted copy would mean the server speaks lines
 * the app never approved, or the tests pin a bank the server doesn't run. Never edit the
 * generated file directly — edit the client source and re-run:
 *
 *   npm run sync:audio     regenerate
 *   npm run check:audio    fail if the generated file is stale (also covered by tests)
 */
import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const checkOnly = process.argv.includes('--check');

const HEADER = `// GENERATED by scripts/sync-narrator-core.mjs from src/lib/narratorCore.ts — do not edit by hand.
// The bank, the calendar resolution, and the assembly rules live in the client source so
// the tests can pin them; this copy exists so the edge function runs the identical logic.
`;

const source = readFileSync(join(root, 'src/lib/narratorCore.ts'), 'utf8');
const generated = HEADER + source;
const target = join(root, 'supabase/functions/audio-render/narratorCore.ts');

if (checkOnly) {
  if (!existsSync(target) || readFileSync(target, 'utf8') !== generated) {
    console.error('audio-render/narratorCore.ts is stale. Run: npm run sync:audio');
    process.exit(1);
  }
  console.log('narrator core in sync.');
} else {
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, generated);
  console.log('wrote supabase/functions/audio-render/narratorCore.ts');
}
